package com.archos.mediacenter.video.utils;

import android.app.Application;
import android.content.*;
import android.database.sqlite.SQLiteDatabase;
import androidx.preference.PreferenceManager;
import com.archos.mediacenter.video.browser.ShortcutDb;
import com.archos.mediacenter.video.utils.backup.*;
import java.io.*;
import java.nio.file.Files;
import java.util.*;
import org.json.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.*;
import static org.junit.Assert.*;

@RunWith(RobolectricTestRunner.class) @Config(application=Application.class,sdk=28) @SQLiteMode(SQLiteMode.Mode.NATIVE)
public class PortableBookmarksTest {
    private Context app;private PreferenceRestoreTransaction transaction;
    private static class Death extends Error {}
    private static final String URI="smb://nas.example/Media";
    @Before public void setup(){app=RuntimeEnvironment.getApplication();for(String db:List.of(BookmarkStoreRecovery.DATABASE,"shortcuts_db","ftp_shortcuts_db"))app.deleteDatabase(db);PreferenceManager.getDefaultSharedPreferences(app).edit().clear().commit();new File(app.getFilesDir(),"supernova-restore/preferences-v1.json").delete();transaction=new PreferenceRestoreTransaction(app);}
    private JSONObject payload()throws Exception{return new JSONObject().put("schema",1).put("rows",new JSONArray().put(new JSONObject().put("id","bookmark:12345678-1234-1234-1234-123456789012:1").put("location",PortableLocations.reference(URI)).put("name","Family library")));}
    private Map<BackupCategory,JSONObject> selected(boolean locations)throws Exception{Map<BackupCategory,JSONObject> result=new EnumMap<>(BackupCategory.class);result.put(BackupCategory.BOOKMARKS,payload());if(locations)result.put(BackupCategory.LOCATIONS,PortableLocations.export(List.of(URI)));return result;}
    private void seed(int version)throws Exception{try(var db=SQLiteDatabase.openOrCreateDatabase(app.getDatabasePath(BookmarkStoreRecovery.DATABASE),null)){db.execSQL("CREATE TABLE shortcuts(_id INTEGER PRIMARY KEY AUTOINCREMENT,uri TEXT NOT NULL,shortcut_name TEXT NOT NULL"+(version==2?",friendly_uri TEXT":"")+")");db.setVersion(version);db.execSQL("INSERT INTO shortcuts(_id,uri,shortcut_name) VALUES(7,?,?)",new Object[]{URI,"Original"});}}
    @Test public void noLocationsOnNewDeviceKeepsUnknownPendingWithoutCreatingAnyDatabase()throws Exception{transaction.apply(transaction.prepare(selected(false),null),()->false);assertFalse(app.getDatabasePath(BookmarkStoreRecovery.DATABASE).exists());assertEquals(1,new JSONObject(PreferenceManager.getDefaultSharedPreferences(app).getString(PortableBookmarks.PENDING,null)).getJSONArray("rows").length());}
    @Test public void explicitLocationsCreateNativeFavouriteAndRealBrowserReaderFindsIt()throws Exception{transaction.apply(transaction.prepare(selected(true),null),()->false);assertEquals("Family library",BookmarkStoreRecovery.capture(app).getJSONArray("rows").getJSONObject(0).getString("name"));assertTrue(new ShortcutDb().isShortcut(app,URI)>0);}
    @Test public void existingExactLocatorBindsWithoutOptInAndLegacySchemaIsNotMigrated()throws Exception{seed(1);transaction.apply(transaction.prepare(selected(false),null),()->false);JSONObject after=BookmarkStoreRecovery.capture(app);assertEquals(1,after.getInt("version"));assertEquals(8,after.getJSONArray("rows").getJSONObject(0).getLong("id"));assertTrue(after.getJSONArray("rows").getJSONObject(0).isNull("friendly"));}
    @Test public void presentEmptyReplacesOnlyFavouritesPreservesPutioAndOtherStoresByteForByte()throws Exception{seed(2);try(var db=SQLiteDatabase.openDatabase(app.getDatabasePath(BookmarkStoreRecovery.DATABASE).getPath(),null,SQLiteDatabase.OPEN_READWRITE)){db.execSQL("INSERT INTO shortcuts(uri,shortcut_name) VALUES('putio:///ACCOUNT','Put.io')");}Map<String,byte[]> originals=new HashMap<>();for(String name:List.of("shortcuts_db","ftp_shortcuts_db")){File file=app.getDatabasePath(name);Files.writeString(file.toPath(),"SOURCE_AND_CREDENTIAL_CANARY");originals.put(name,Files.readAllBytes(file.toPath()));}transaction.apply(transaction.prepare(Map.of(BackupCategory.BOOKMARKS,new JSONObject().put("schema",1).put("rows",new JSONArray())),null),()->false);JSONArray after=BookmarkStoreRecovery.capture(app).getJSONArray("rows");assertEquals(1,after.length());assertEquals("putio:///ACCOUNT",after.getJSONObject(0).getString("uri"));for(String name:originals.keySet())assertArrayEquals(originals.get(name),Files.readAllBytes(app.getDatabasePath(name).toPath()));}
    @Test public void exportOmitsLocatorsDefaultNamesFriendlyPathsAndPutioButRetainsCustomLabel()throws Exception{seed(2);try(var db=SQLiteDatabase.openDatabase(app.getDatabasePath(BookmarkStoreRecovery.DATABASE).getPath(),null,SQLiteDatabase.OPEN_READWRITE)){db.execSQL("INSERT INTO shortcuts(uri,shortcut_name,friendly_uri) VALUES('file:///PRIVATE/File.mkv','File.mkv','PRIVATE_HINT'),('putio:///ACCOUNT','Put.io',NULL)");}var exported=LogicalBackupExporter.collect(app,Set.of(BackupCategory.BOOKMARKS),()->false);String text=exported.toString();for(String forbidden:List.of("PRIVATE","File.mkv","ACCOUNT","smb://","file:///"))assertFalse(forbidden,text.contains(forbidden));assertEquals(2,exported.get(BackupCategory.BOOKMARKS).getJSONArray("rows").length());assertTrue(text.contains("Original"));var explicit=LogicalBackupExporter.collect(app,Set.of(BackupCategory.BOOKMARKS,BackupCategory.LOCATIONS),()->false);assertEquals(2,explicit.get(BackupCategory.LOCATIONS).getJSONArray("rows").length());}
    @Test public void credentialLocationsFailBeforeArchiveAllocationAndNeverEchoSecrets()throws Exception{seed(2);try(var db=SQLiteDatabase.openDatabase(app.getDatabasePath(BookmarkStoreRecovery.DATABASE).getPath(),null,SQLiteDatabase.OPEN_READWRITE)){db.execSQL("UPDATE shortcuts SET uri='smb://user:PASSWORD_CANARY@nas/share'");}String before=BookmarkStoreRecovery.capture(app).toString();try{LogicalBackupExporter.preparePrivate(app,Set.of(BackupCategory.BOOKMARKS),()->false);fail();}catch(IOException expected){assertFalse(expected.getMessage().contains("PASSWORD_CANARY"));}assertEquals(before,BookmarkStoreRecovery.capture(app).toString());assertFalse(new File(app.getCacheDir(),"supernova-logical-backups").exists());}
    @Test public void crashBeforeDecisionRemovesOnlyNewStoreAndRestoresPendingPreference()throws Exception{for(var boundary:List.of(PreferenceRestoreTransaction.Checkpoint.JOURNAL_DURABLE,PreferenceRestoreTransaction.Checkpoint.DEFAULT_DURABLE,PreferenceRestoreTransaction.Checkpoint.BOOKMARKS_PREPARED,PreferenceRestoreTransaction.Checkpoint.PREFERENCES_DURABLE)){try{transaction.apply(transaction.prepare(selected(true),null),()->false,at->{if(at==boundary)throw new Death();});fail();}catch(Death expected){}assertEquals(PreferenceRestoreTransaction.Recovery.ROLLED_BACK,transaction.recover());assertFalse(app.getDatabasePath(BookmarkStoreRecovery.DATABASE).exists());assertFalse(PreferenceManager.getDefaultSharedPreferences(app).contains(PortableBookmarks.PENDING));}}
    @Test public void crashAfterDecisionReplaysUncommittedStore()throws Exception{try{transaction.apply(transaction.prepare(selected(true),null),()->false,at->{if(at==PreferenceRestoreTransaction.Checkpoint.COMMIT_MARKER_DURABLE)throw new Death();});fail();}catch(Death expected){}assertEquals(PreferenceRestoreTransaction.Recovery.COMPLETED,transaction.recover());assertEquals("Family library",BookmarkStoreRecovery.capture(app).getJSONArray("rows").getJSONObject(0).getString("name"));}
    @Test public void acknowledgedCommitPreservesLaterManualChangeDuringRecovery()throws Exception{try{transaction.apply(transaction.prepare(selected(true),null),()->false,at->{if(at==PreferenceRestoreTransaction.Checkpoint.BOOKMARKS_DURABLE)throw new Death();});fail();}catch(Death expected){}try(var db=SQLiteDatabase.openDatabase(app.getDatabasePath(BookmarkStoreRecovery.DATABASE).getPath(),null,SQLiteDatabase.OPEN_READWRITE)){db.execSQL("UPDATE shortcuts SET shortcut_name='Later manual change'");}assertEquals(PreferenceRestoreTransaction.Recovery.COMPLETED,transaction.recover());assertEquals("Later manual change",BookmarkStoreRecovery.capture(app).getJSONArray("rows").getJSONObject(0).getString("name"));}
    @Test public void legacyOriginalsAndSequenceRecoverExactlyOnFailure()throws Exception{seed(1);String before=BookmarkStoreRecovery.capture(app).toString();try{transaction.apply(transaction.prepare(selected(true),null),()->false,at->{if(at==PreferenceRestoreTransaction.Checkpoint.BOOKMARKS_PREPARED)throw new IOException("Injected");});fail();}catch(PreferenceRestoreTransaction.Failure expected){assertEquals(PreferenceRestoreTransaction.Recovery.ROLLED_BACK,expected.outcome);}assertEquals(before,BookmarkStoreRecovery.capture(app).toString());}
    @Test public void unsupportedSchemaFailsBeforeMutation()throws Exception{seed(2);try(var db=SQLiteDatabase.openDatabase(app.getDatabasePath(BookmarkStoreRecovery.DATABASE).getPath(),null,SQLiteDatabase.OPEN_READWRITE)){db.setVersion(900);}try{transaction.prepare(selected(true),null);fail();}catch(IOException expected){}assertFalse(new File(app.getFilesDir(),"supernova-restore/preferences-v1.json").exists());}
}
